"use client"

import { useState, useEffect } from "react"
import { Button } from "@/components/ui/button"
import { AdminAuth } from "@/components/admin-auth"
import { PostCard } from "@/components/post-card"
import { PostEditor } from "@/components/post-editor"
import { Plus, Bell } from "lucide-react"

interface Post {
  id: string
  title: string
  content: string
  createdAt: string
  updatedAt?: string
}

const STORAGE_KEY = "notices_posts"

export default function NoticesPage() {
  const [posts, setPosts] = useState<Post[]>([])
  const [showAuth, setShowAuth] = useState(false)
  const [showEditor, setShowEditor] = useState(false)
  const [editingPost, setEditingPost] = useState<Post | null>(null)
  const [isAuthenticated, setIsAuthenticated] = useState(false)

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY)
    if (saved) {
      setPosts(JSON.parse(saved))
    } else {
      // Default notice
      const defaultPost: Post = {
        id: "1",
        title: "사이트 오픈 안내",
        content: "작가의 서재가 새롭게 오픈했습니다.\n\n본 사이트는 웹소설 작가분들의 창작 활동을 지원하기 위해 만들어졌습니다. AI 기반 정보검색엔진을 통해 무협, 판타지 장르의 다양한 정보를 검색하고, 새로운 설정을 창조해보세요.\n\n앞으로도 많은 관심과 이용 부탁드립니다.",
        createdAt: new Date().toISOString(),
      }
      setPosts([defaultPost])
      localStorage.setItem(STORAGE_KEY, JSON.stringify([defaultPost]))
    }
  }, [])

  const savePosts = (newPosts: Post[]) => {
    setPosts(newPosts)
    localStorage.setItem(STORAGE_KEY, JSON.stringify(newPosts))
  }

  const handleNewPost = () => {
    if (!isAuthenticated) {
      setShowAuth(true)
    } else {
      setEditingPost(null)
      setShowEditor(true)
    }
  }

  const handleAuthenticated = () => {
    setIsAuthenticated(true)
    setShowAuth(false)
    setEditingPost(null)
    setShowEditor(true)
  }

  const handleSavePost = (title: string, content: string) => {
    if (editingPost) {
      const updatedPosts = posts.map(post =>
        post.id === editingPost.id
          ? { ...post, title, content, updatedAt: new Date().toISOString() }
          : post
      )
      savePosts(updatedPosts)
    } else {
      const newPost: Post = {
        id: Date.now().toString(),
        title,
        content,
        createdAt: new Date().toISOString(),
      }
      savePosts([newPost, ...posts])
    }
    setShowEditor(false)
    setEditingPost(null)
  }

  const handleEditPost = (post: Post) => {
    if (!isAuthenticated) {
      setEditingPost(post)
      setShowAuth(true)
    } else {
      setEditingPost(post)
      setShowEditor(true)
    }
  }

  const handleEditAuthenticated = () => {
    setIsAuthenticated(true)
    setShowAuth(false)
    setShowEditor(true)
  }

  const handleDeletePost = (postId: string) => {
    if (!isAuthenticated) {
      setShowAuth(true)
      return
    }
    if (confirm("정말 이 공지사항을 삭제하시겠습니까?")) {
      const newPosts = posts.filter(post => post.id !== postId)
      savePosts(newPosts)
    }
  }

  return (
    <div className="min-h-screen p-6 md:p-10">
      <div className="max-w-3xl mx-auto">
        {/* Header */}
        <div className="flex items-center justify-between mb-10 pt-8 md:pt-0">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-secondary rounded-sm">
              <Bell className="h-5 w-5 text-foreground" />
            </div>
            <div>
              <h1 className="text-2xl md:text-3xl font-bold text-foreground">
                공지사항
              </h1>
              <p className="text-muted-foreground text-sm">
                사이트 소식과 업데이트
              </p>
            </div>
          </div>
          <Button onClick={handleNewPost} className="gap-2">
            <Plus className="h-4 w-4" />
            <span className="hidden sm:inline">새 공지 작성</span>
          </Button>
        </div>

        {/* Posts */}
        <div className="space-y-6">
          {posts.length === 0 ? (
            <div className="text-center py-20 text-muted-foreground border border-border rounded-sm bg-card">
              아직 등록된 공지사항이 없습니다
            </div>
          ) : (
            posts.map(post => (
              <PostCard
                key={post.id}
                post={post}
                onEdit={() => handleEditPost(post)}
                onDelete={() => handleDeletePost(post.id)}
                showActions={isAuthenticated}
              />
            ))
          )}
        </div>
      </div>

      {/* Admin Auth Modal */}
      {showAuth && (
        <AdminAuth
          onAuthenticated={editingPost ? handleEditAuthenticated : handleAuthenticated}
          onCancel={() => {
            setShowAuth(false)
            setEditingPost(null)
          }}
        />
      )}

      {/* Post Editor Modal */}
      {showEditor && (
        <PostEditor
          initialTitle={editingPost?.title || ""}
          initialContent={editingPost?.content || ""}
          onSave={handleSavePost}
          onCancel={() => {
            setShowEditor(false)
            setEditingPost(null)
          }}
        />
      )}
    </div>
  )
}
